package com.ynxweb4.music;
import org.json.*;import android.content.Context;import java.io.*;import java.nio.file.*;import java.util.*;
// Local cache/software-file model only. No MusicApi instance, SDK grant, proof, listener or network call.
public final class IndependentCacheCheck {
 interface Check {void run()throws Exception;}static int pass=0,fail=0;static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}static void test(String name,Check work){try{work.run();pass++;System.out.println("PASS "+name);}catch(Throwable e){fail++;System.out.println("FAIL "+name+": "+e);}}
 static final String account="ynx1"+"a".repeat(38),track="trk_"+"a".repeat(24);static final MusicIO.Guard guard=()->{};
 static class Fixture{Context context;MusicStore store;JSONObject snapshot;Fixture()throws Exception{File dir=Files.createTempDirectory(Path.of("fixture-state"),"cache-").toFile();context=new Context(dir);store=MusicStore.selectAccount(context,account);byte[] wav=new byte[44];System.arraycopy("RIFF".getBytes(),0,wav,0,4);System.arraycopy("WAVE".getBytes(),0,wav,8,4);File file=store.offline(track);file.getParentFile().mkdirs();Files.write(file.toPath(),wav);snapshot=new JSONObject().put("profile",new JSONObject().put("account",account).put("displayName","original")).put("listener",new JSONObject().put("account",account).put("favorites",new JSONArray()).put("queue",new JSONArray()).put("downloads",new JSONObject())).put("catalog",new JSONArray().put(new JSONObject().put("id",track).put("audioSha256",MusicApi.fileDigest(file)))).put("playlists",new JSONArray().put(new JSONObject().put("name","original playlist")));store.commitSnapshot(snapshot,guard);}}
 public static void main(String[] args)throws Exception{Files.createDirectories(Path.of("fixture-state"));
 test("profile and verified download preserve latest unrelated fields",()->{Fixture f=new Fixture();JSONObject s=f.store.load();s.put("aiEnabled",false).put("uploadIntent",new JSONObject().put("key","original retained metadata"));f.store.save(s);JSONObject profile=f.store.commitProfile(new JSONObject().put("account",account).put("displayName","confirmed profile"),guard);check(profile.has("uploadIntent")&&!profile.getBoolean("aiEnabled"),"profile lost unrelated cache");JSONObject next=f.store.commitDownload(track,guard);check(next.has("uploadIntent")&&!next.getBoolean("aiEnabled")&&next.getJSONObject("downloads").getString(track).equals("available"),"download lost original fields/audio verification");});
 test("same original library tuple cold readback acknowledges without dispatch",()->{Fixture f=new Fixture();JSONObject next=f.store.load().put("favorites",new JSONArray().put(track));JSONObject prepared=f.store.prepareLibrary(next,guard),intent=prepared.getJSONObject("libraryIntent");JSONObject returned=new JSONObject(f.snapshot.toString()).put("listener",new JSONObject(intent.toString()));MusicStore cold=MusicStore.selectAccount(f.context,account);JSONObject result=cold.commitSnapshot(returned,guard);check(!result.has("libraryIntent")&&result.getJSONArray("favorites").getString(0).equals(track),"cold tuple did not confirm");});
 test("mismatched snapshot and old intent cannot consume successor",()->{Fixture f=new Fixture();JSONObject older=f.store.prepareLibrary(f.store.load().put("favorites",new JSONArray().put(track)),guard).getJSONObject("libraryIntent");JSONObject latest=f.store.prepareLibrary(f.store.load().put("queue",new JSONArray().put(track)),guard).getJSONObject("libraryIntent");check(!f.store.acknowledgeLibrary(older,guard),"old intent consumed new");JSONObject refreshed=f.store.commitSnapshot(f.snapshot,guard);check(refreshed.getJSONObject("libraryIntent").getString("id").equals(latest.getString("id"))&&refreshed.getJSONArray("queue").length()==1,"mismatched snapshot lost pending local edit");});
 test("changed account refuses original cache commit",()->{Fixture f=new Fixture();MusicStore.selectAccount(f.context,"ynx1"+"b".repeat(38));boolean denied=false;try{f.store.commitProfile(new JSONObject().put("account",account),guard);}catch(IOException e){denied=true;}check(denied,"old account published");});
 test("P2 library edit must preserve upload intent persisted after Activity snapshot capture",()->{Fixture f=new Fixture();JSONObject activity=f.store.load();String key="music-upload-"+UUID.randomUUID();byte[] wav=new byte[44];System.arraycopy("RIFF".getBytes(),0,wav,0,4);System.arraycopy("WAVE".getBytes(),0,wav,8,4);String digest=f.store.stageUpload(new ByteArrayInputStream(wav),key,guard);JSONObject intent=new JSONObject().put("key",key).put("audioSHA256",digest);f.store.updateUpload(intent,null,false);JSONObject newer=f.store.load();newer.put("position",99);newer.getJSONObject("remote").getJSONArray("playlists").getJSONObject(0).put("name","newer original playlist");f.store.save(newer);activity.put("favorites",new JSONArray().put(track));JSONObject actual=f.store.prepareLibrary(activity,guard);System.out.println("MODEL newer upload="+actual.has("uploadIntent")+", position="+actual.getInt("position")+", playlist="+actual.getJSONObject("remote").getJSONArray("playlists").getJSONObject(0).getString("name")+", staged audio retained="+f.store.uploadFile(key).isFile());check(actual.has("uploadIntent")&&actual.getJSONObject("uploadIntent").getString("key").equals(key),"new prepareLibrary replaced full stale Activity snapshot and deleted original pending upload selector");});
 System.out.println("RESULT pass="+pass+" fail="+fail+" SDK/auth/network/device=NOT_RUN");if(fail>0)System.exit(1);}
}
